// 支撑强度渲染：红角标 + 悬浮提示
const renderWeight = (value) => {
  const level = value ? '高/中/低' : '待补';
  return (
    <Tooltip title={value ? `权重: ${value}` : '请补填权重'}>
      <span style={{ position: 'relative' }}>
        {level}
        {!value && <Badge dot color="red" style={{ position: 'absolute', top: 0, right: -8 }} />}
      </span>
    </Tooltip>
  );
};

const validateThreshold = (t1, t2) => {
  if (t1 <= 0 || t2 >= 1 || t1 >= t2) {
    throw new Error('阈值需满足 0 < T1 < T2 < 1');
  }
  // 保存后触发重新计算所有支撑权重
  recalcAllWeights({ low: t1, high: t2 });
};
